// A stand-in for the Sass compiler (only what this test needs: `@use 'name';` found through the importers, then the file's text), so the test needs no download.
const fs = require('node:fs');
const { fileURLToPath } = require('node:url');
exports.compileStringAsync = async (code, { importers = [], url }) => {
  const loaded = [url];
  // An importer's `findFileUrl` may be asynchronous, as in the real compiler.
  const names = [...code.matchAll(/^@use '([^']+)';\s*$/gm)].map((m) => m[1]);
  const texts = {};
  for (const name of names) {
    let found = null;
    for (const importer of importers) {
      found = await importer.findFileUrl(name);
      if (found) break;
    }
    if (!found) throw new Error("Can't find stylesheet to import: " + name);
    loaded.push(found);
    texts[name] = fs.readFileSync(fileURLToPath(found) + '.scss', 'utf8');
  }
  const css = code.replace(/^@use '([^']+)';\s*$/gm, (_, name) => texts[name]);
  return { css, loadedUrls: loaded };
};
